/* _chat/chat.js: the chat kit shared by demo/chat and demo/mcp. README.md beside this file has the markup.

   The thread in the HTML is the script. Each .ck-row inside a [data-ck-thread] is one message, in order, and
   conversation() turns them into tour steps: a person's message is typed (into the composer, or in place) and
   sent; an agent's turn shows the typing dots, then its rows arrive one after another, text streaming word by
   word, a tool call running and finishing, a card opening. Rows take height as they arrive (data-tour-grow,
   measured by the engine), so the thread rises smoothly at every frame and any moment renders on its own.

     import { prepare, conversation } from '../_chat/chat.js';
     prepare(win);                                     // once, before new Tour(): names rows, splits words, adds the dots
     steps.push(...conversation(win, thread, { chapters, before, after }));

   Pacing lives on the rows: data-think (s of dots before an agent turn), data-read (s held after a row), data-run
   (s a tool call takes), data-cps (a person's typing speed). Interactions inside cards (taps on a slot, a Send
   button) are ordinary tour steps the script adds after a row: after: { 'row-name': [tap('@slot'), …] }. */
import { show, hide, set, tween, type, click, stream, pause, mark, chapter } from '../tour/tour.js';

const WORD = /(\s+)/;
const rnd = (n) => { const x = Math.sin(n * 77.3 + 5.1) * 43758.5453; return x - Math.floor(x); };

/* ── DOM preparation: run once, before new Tour() ─────────────────────────────────────────────────── */
export function prepare(win) {
  const avatar = win.querySelector('[data-ck-avatar]');
  [...win.querySelectorAll('[data-ck-thread]')].forEach((thread, ti) => {
    const rows = [...thread.children].filter((r) => r.classList.contains('ck-row'));
    let prev = null;
    rows.forEach((row, i) => {
      if (!row.dataset.tour) row.dataset.tour = `ck-${ti}-${i}`;
      const from = row.dataset.from || 'agent', lead = from === 'agent' && (!prev || (prev.dataset.from || 'agent') !== 'agent');
      row.dataset.from = from;
      row.classList.toggle('is-lead', lead || from === 'person');
      if (row.classList.contains('is-static')) { prev = row; return; }   // there from the start (a date line, an intro)
      row.setAttribute('data-tour-grow', '');
      row.querySelectorAll('.ck-tool-body, [data-ck-swap] > :first-child').forEach((b) => b.setAttribute('data-tour-grow', ''));
      row.querySelectorAll('[data-stream]').forEach(splitWords);
      if (row.dataset.via === 'inline') {             // typed in place: keep the words for type(), start it empty
        const said = row.querySelector('[data-said]') || row.querySelector('.ck-bubble, p');
        if (said && !said.dataset.say) { said.dataset.say = said.textContent.trim(); said.textContent = ''; said.setAttribute('data-said', ''); }
      }
      if (lead && avatar && thread.dataset.avatars !== 'off' && !row.querySelector('.ck-av')) row.querySelector('.ck-pad')?.prepend(avatarOf(avatar));
      if (lead && thread.dataset.typing !== 'off' && row.dataset.think !== '0') {   // the typing dots, a row of their own
        const dots = document.createElement('div');
        dots.className = 'ck-row is-typing is-lead'; dots.dataset.from = 'agent'; dots.dataset.tour = row.dataset.tour + '-dots';
        dots.setAttribute('data-tour-grow', ''); dots.setAttribute('aria-hidden', 'true');
        dots.innerHTML = '<div class="ck-pad"><span class="ck-dots"><i></i><i></i><i></i></span></div>';
        if (avatar && thread.dataset.avatars !== 'off') dots.firstChild.prepend(avatarOf(avatar));
        row.before(dots);
      }
      prev = row;
    });
  });
}
function avatarOf(src) { const a = document.createElement('span'); a.className = 'ck-av'; a.setAttribute('aria-hidden', 'true'); a.innerHTML = src.innerHTML; return a; }

/* wrap each word of a [data-stream] element in <span class="w">, keeping its markup (bold, links, code, lists) */
function splitWords(el) {
  const walk = document.createTreeWalker(el, NodeFilter.SHOW_TEXT), nodes = [];
  while (walk.nextNode()) nodes.push(walk.currentNode);
  for (const n of nodes) {
    if (!n.textContent.trim() || n.parentElement.closest('.w')) continue;
    const f = document.createDocumentFragment();
    for (const part of n.textContent.split(WORD)) {
      if (!part) continue;
      if (/^\s+$/.test(part)) f.append(part); else { const s = document.createElement('span'); s.className = 'w'; s.textContent = part; f.append(s); }
    }
    n.replaceWith(f);
  }
}

/* ── the thread as steps ──────────────────────────────────────────────────────────────────────────── */
/* o.chapters  { rowName: ['01 / 04', 'Find a <em>time</em>', 'One line.'] }  a chapter starts at that row
   o.before / o.after  { rowName: [steps] }   extra steps around a row (taps inside a card, a zoom)
   o.composer  { field: '@ck-input', input: '@ck-input', send: '@ck-send' }  where a person types (chat)
   o.prefix    a string put before every mark: marks are `${prefix}${rowName}`                              */
export function conversation(win, thread, o = {}) {
  thread = typeof thread === 'string' ? win.querySelector(thread) : thread || win.querySelector('[data-ck-thread]');
  const C = { field: '@ck-input', input: '@ck-input', send: '@ck-send', ...(o.composer || {}) };
  const steps = [], at = (r) => `@${r.dataset.tour}`;
  let focused = false;
  [...thread.children].filter((r) => r.classList.contains('ck-row') && !r.classList.contains('is-static')).forEach((row, i) => {
    const name = row.dataset.tour, from = row.dataset.from, kind = row.dataset.kind || (row.classList.contains('is-typing') ? 'dots' : 'text');
    if (kind === 'dots') return;                               // played by the row it belongs to
    const ch = o.chapters?.[name]; if (ch) steps.push(chapter(...ch));
    steps.push(mark((o.prefix || '') + name));
    steps.push(...(o.before?.[name] || []));
    const read = row.dataset.read != null ? +row.dataset.read : null;

    if (from === 'person') {
      const said = row.querySelector('[data-said]');
      if (row.dataset.via === 'inline' && said) {             // typed in place, then it stands (mcp)
        steps.push(show(at(row), { dur: .3, ease: 'out' }));
        steps.push(type(`${at(row)} [data-said]`, said.dataset.say, { rhythm: 'human', cps: +row.dataset.cps || 15, lead: .35, caret: .45 }));
        steps.push(pause(read ?? .45));
      } else if (row.dataset.via && row.dataset.via.startsWith('@')) {   // a tap on a chip or a button sends it
        steps.push(click(row.dataset.via, { dur: .85 }), set(row.dataset.via, { class: '+is-picked' }));
        steps.push(show(at(row), { dur: .42, ease: 'out', wait: .12, block: true }), pause(read ?? .55));
      } else {                                                 // typed into the composer and sent
        const text = (row.querySelector('.ck-bubble') || row).textContent.trim().replace(/\s+/g, ' ');
        if (!focused) { steps.push(click(C.field, { dur: .9, aim: [.82, .5] })); focused = true; }
        steps.push(type(C.input, text, { rhythm: 'human', cps: +row.dataset.cps || 16, lead: .2, caret: .5 }));
        steps.push(pause(.2), click(C.send, { dur: .55 }));
        steps.push(set(C.input, { text: '', class: '-is-caret' }), show(at(row), { dur: .42, ease: 'out', block: true }), pause(read ?? .55));
      }
    } else {
      const dots = row.previousElementSibling?.classList.contains('is-typing') ? row.previousElementSibling : null;
      if (dots) {
        const think = row.dataset.think != null ? +row.dataset.think : .75 + .35 * rnd(i);
        steps.push(show(at(dots), { dur: .3, ease: 'out' }), tween(`${at(dots)} .ck-dots`, '--tk', 0, think * 1.6, { dur: think + .3, ease: 'linear' }));
        steps.push(pause(think + .3), hide(at(dots), { dur: .26 }));
      }
      steps.push(show(at(row), { dur: .4, ease: 'out' }));
      if (kind === 'tool') steps.push(...toolSteps(row, at(row)));
      const words = row.querySelectorAll('[data-stream] .w');
      if (words.length) steps.push(stream(`${at(row)} [data-stream] .w`, { every: .034, jitter: .55, dur: .22, wait: kind === 'tool' ? 0 : .12 }));
      const parts = row.querySelectorAll('[data-ck-in]');      // a card's parts settle in one after another
      if (parts.length) steps.push(show(`${at(row)} [data-ck-in]`, { dur: .45, stagger: .07, ease: 'out', wait: words.length ? 0 : .15, block: true }));
      const grows = row.querySelectorAll('[data-ck-grow]');    // bars, meters: --g 0 → 1
      if (grows.length) steps.push(tween(`${at(row)} [data-ck-grow]`, '--g', 0, 1, { dur: .7, stagger: .05, ease: 'out', block: true }));
      steps.push(pause(read ?? readTime(row, kind)));
    }
    steps.push(...(o.after?.[name] || []));
  });
  return steps;
}

/* a tool call: running (a spinner, the arguments; in an open block the result streams in), then done, then it folds */
function toolSteps(row, me) {
  const tool = row.querySelector('.ck-tool'), run = +(row.dataset.run || .9), open = row.dataset.open != null;
  const s = [set(`${me} .ck-tool`, { class: '+is-running' }), tween(`${me} .ck-tool`, '--spin', 0, run * 1.3, { dur: run + .2, ease: 'linear' })];
  const meta = tool?.querySelector('[data-done]');
  if (open) {
    s.push(show(`${me} .ck-tool-body`, { dur: .45, ease: 'out', wait: .15 }));
    const lines = tool.querySelectorAll('.ck-out > *');
    if (lines.length) s.push(stream(`${me} .ck-out > *`, { every: .07, jitter: .4, dur: .16, wait: Math.max(.25, run - .1) }));
    else s.push(pause(run));
  } else s.push(pause(run));
  s.push(set(`${me} .ck-tool`, { class: '-is-running +is-done' }));
  if (meta) s.push(set(`${me} [data-done]`, { text: meta.dataset.done }));
  if (open && row.dataset.fold !== 'off') s.push(pause(+(row.dataset.hold || 1.3)), hide(`${me} .ck-tool-body`, { dur: .5 }));
  else s.push(pause(.35));
  return s;
}
function readTime(row, kind) {
  const n = (row.textContent.match(/\S+/g) || []).length;
  return kind === 'tool' ? .2 : Math.min(2.2, Math.max(.7, .45 + n * .045));
}

/* ── the page helpers ─────────────────────────────────────────────────────────────────────────────── */
/* copy buttons: <button data-ck-copy="#id-or-text">Copy</button> copies the element's text (or the attribute's text) */
export function copyButtons(root) {
  const on = async (e) => {
    const b = e.target.closest('[data-ck-copy]'); if (!b || !root.contains(b)) return;
    e.preventDefault();
    const v = b.dataset.ckCopy, el = v.startsWith('#') || v.startsWith('.') ? root.querySelector(v) : null;
    const text = el ? el.innerText.trim() : v;
    try { await navigator.clipboard.writeText(text); } catch { const ta = Object.assign(document.createElement('textarea'), { value: text }); document.body.append(ta); ta.select(); document.execCommand('copy'); ta.remove(); }
    const was = b.dataset.label || b.textContent; b.dataset.label = was; b.textContent = b.dataset.copied || 'Copied'; b.classList.add('is-copied');
    clearTimeout(b._t); b._t = setTimeout(() => { b.textContent = was; b.classList.remove('is-copied'); }, 1800);
    const say = root.querySelector('[data-ck-said]'); if (say) say.textContent = `${b.dataset.what || 'Text'} copied`;
  };
  root.addEventListener('click', on);
  return () => root.removeEventListener('click', on);
}

/* tabs: [data-ck-tabs] holding [role=tab] buttons (aria-controls) and their [role=tabpanel]s */
export function tabs(root) {
  const off = [];
  for (const list of root.querySelectorAll('[data-ck-tabs]')) {
    const tabsEls = [...list.querySelectorAll('[role=tab]')];
    const pick = (t, focus) => {
      for (const x of tabsEls) { const on = x === t; x.setAttribute('aria-selected', on); x.tabIndex = on ? 0 : -1; const p = root.querySelector('#' + x.getAttribute('aria-controls')); if (p) p.hidden = !on; }
      if (focus) t.focus();
    };
    const click = (e) => { const t = e.target.closest('[role=tab]'); if (t && list.contains(t)) pick(t); };
    const key = (e) => {
      const i = tabsEls.indexOf(document.activeElement); if (i < 0) return;
      const j = { ArrowRight: i + 1, ArrowLeft: i - 1, Home: 0, End: tabsEls.length - 1 }[e.key]; if (j == null) return;
      e.preventDefault(); pick(tabsEls[(j + tabsEls.length) % tabsEls.length], true);
    };
    list.addEventListener('click', click); list.addEventListener('keydown', key);
    off.push(() => { list.removeEventListener('click', click); list.removeEventListener('keydown', key); });
  }
  return () => off.forEach((f) => f());
}

/* tool blocks fold and unfold when a visitor clicks their head (once the film has left them alone) */
export function foldable(root) {
  const on = (e) => {
    const h = e.target.closest('.ck-tool-head'); if (!h || !root.contains(h)) return;
    const t = h.closest('.ck-tool'), body = t.querySelector('.ck-tool-body'); if (!body) return;
    const was = t.classList.contains('is-user-open') || (!t.classList.contains('is-user-shut') && +getComputedStyle(body).getPropertyValue('--in') > .5);
    t.classList.toggle('is-user-open', !was); t.classList.toggle('is-user-shut', was); h.setAttribute('aria-expanded', String(!was));
  };
  root.addEventListener('click', on);
  return () => root.removeEventListener('click', on);
}

/* StyleFeatures scaffolds: shared runtime. Safe to load twice.
   - [data-reveal] fades in on scroll
   - .ph-video gets a play/pause button, a running timeline and a timecode, so a video slot behaves like one
     (data-dur="12" seconds, data-autoplay for background loops)
   - press N (or ?clean in the URL) to hide the notes */
if (!window.__sfScaffold) {
  window.__sfScaffold = true;
  const reduce = matchMedia('(prefers-reduced-motion: reduce)').matches;
  const io = new IntersectionObserver((es) => es.forEach((e) => { if (e.isIntersecting) { e.target.classList.add('is-in'); io.unobserve(e.target); } }),
    { rootMargin: '0px 0px -8% 0px', threshold: 0.06 });
  const PLAY = '<svg viewBox="0 0 20 20" aria-hidden="true"><path d="M6 3.8v12.4L16 10z" fill="currentColor"/></svg>';
  const PAUSE = '<svg viewBox="0 0 20 20" aria-hidden="true"><path d="M5.5 4h3v12h-3zM11.5 4h3v12h-3z" fill="currentColor"/></svg>';
  const fmt = (s) => `${Math.floor(s / 60)}:${String(Math.floor(s % 60)).padStart(2, '0')}`;

  function video(el) {
    if (el.__sf) return; el.__sf = true;
    const dur = +el.dataset.dur || 12, loop = el.hasAttribute('data-autoplay') || el.hasAttribute('data-loop');
    const btn = document.createElement('button');
    btn.className = 'ph-play'; btn.type = 'button'; btn.setAttribute('aria-label', 'Play video'); btn.innerHTML = PLAY;
    const bar = document.createElement('div'); bar.className = 'ph-bar'; bar.setAttribute('aria-hidden', 'true');
    bar.innerHTML = `<span class="t">0:00</span><span class="ph-track"><i></i></span><span>${fmt(dur)}</span>`;
    if (el.hasAttribute('data-nobar')) bar.hidden = true;
    if (el.hasAttribute('data-nobutton')) btn.hidden = true;
    el.append(btn, bar);
    const t = bar.querySelector('.t');
    let pos = 0, playing = false, last = 0, raf = 0, visible = true;
    const draw = () => { el.style.setProperty('--p', pos / dur); t.textContent = fmt(pos); el.style.setProperty('--sf-t', pos); };
    const tick = (now) => {
      if (!playing) return;
      pos += Math.min(.1, (now - last) / 1000); last = now;
      if (pos >= dur) { if (loop) pos = 0; else { pos = dur; set(false); } }
      draw(); el.dispatchEvent(new CustomEvent('sf:time', { detail: { t: pos, dur } }));
      if (visible) raf = requestAnimationFrame(tick);
    };
    function set(on) {
      playing = on; el.classList.toggle('is-playing', on);
      btn.innerHTML = on ? PAUSE : PLAY; btn.setAttribute('aria-label', on ? 'Pause video' : 'Play video');
      cancelAnimationFrame(raf);
      if (on) { if (pos >= dur) pos = 0; last = performance.now(); raf = requestAnimationFrame(tick); }
    }
    btn.addEventListener('click', (e) => { e.stopPropagation(); set(!playing); });
    el.sfVideo = { play: () => set(true), pause: () => set(false), seek: (s) => { pos = Math.max(0, Math.min(dur, s)); draw(); }, get t() { return pos; }, dur };
    new IntersectionObserver(([e]) => { visible = e.isIntersecting; if (visible && playing) { last = performance.now(); cancelAnimationFrame(raf); raf = requestAnimationFrame(tick); } }).observe(el);
    if (el.hasAttribute('data-autoplay') && !reduce) set(true);
    draw();
  }

  const scan = (root = document) => {
    root.querySelectorAll('[data-reveal]:not(.is-in)').forEach((el) => (reduce ? el.classList.add('is-in') : io.observe(el)));
    root.querySelectorAll('.ph-video').forEach(video);
  };
  window.sfScan = scan;
  window.sfVideo = video;
  const boot = () => scan();
  if (document.readyState === 'loading') addEventListener('DOMContentLoaded', boot); else boot();
  if (location.search.includes('clean')) document.documentElement.classList.add('sf-clean');
  if (location.search.includes('thumb')) document.documentElement.classList.add('sf-thumb');
  if (innerWidth < 700) addEventListener('DOMContentLoaded', () => document.querySelector('.sf-spec')?.classList.add('is-min'));
  addEventListener('keydown', (e) => { if (e.key === 'n' && !/INPUT|TEXTAREA/.test(document.activeElement?.tagName)) document.documentElement.classList.toggle('sf-clean'); });
  const down = () => document.documentElement.classList.toggle('is-down', scrollY > 24);
  addEventListener('scroll', down, { passive: true }); down();
}

/* The MCP film's script. Each conversation is a thread in section.html (.mcp-conv), played in order by
   ../_chat/chat.js: the person's line is typed in place, the tool call runs ("server · tool", its arguments, its
   result streaming in), folds to one line, and the agent answers. section.js strings the conversations together
   (the tabs follow along) and ends on the way to add the server. Pacing per message is on the rows (data-run,
   data-hold, data-read, data-cps: ../_chat/README.md). Check any moment with ?t=12.5; ?record&ratio=16:9|1:1|9:16. */
export default {
  size: [600, 'auto'],       // design px wide; the height follows the screen (data-size="600xauto" on the window)
  sizeTall: [400, 'auto'],   // phones and 9:16
  intro: 0,                  // no band: the first line being typed is the opening
  lead: .9,                  // seconds on the empty transcript before the first key
  between: 1.8,              // seconds each finished conversation stays before the next one
  settle: .6,
  outro: 6,                  // seconds held on the ending (Add the MCP): long, so a recording ends on it
  // extra steps around a row, by its data-tour name (none needed for the placeholder)
  before: {}, after: {},
};

// demo/mcp: a toured text chat between a person and their agent using one MCP server, then the way to add it.
// The conversations (.mcp-conv) play one after another on the engine's manual driver, on their own from the moment
// the page opens; the tabs (one per tool) jump to a conversation, "Add the MCP" jumps to the ending. The ending is
// live: the big button and Copy buttons copy, the config tabs switch, tool calls fold open when clicked.
// ?t=12.5 freezes a moment; ?record&ratio=16:9|1:1|9:16 plays it once and holds on the ending.
import { Tour, include, show, hide, set, pause, mark, chapter } from '../tour/tour.js';
import { prepare, conversation, copyButtons, tabs, foldable } from '../_chat/chat.js';
import script from './script.js';

export default function init(root) {
  // harvested card fragments (<div data-tour-include="chat/fragments/booking.html">) are fetched before anything is measured
  let stop = null, dead = false;
  if (root.querySelector('[data-tour-include]')) include(root).then(() => { if (!dead) stop = boot(root); }); else stop = boot(root);
  return () => { dead = true; stop?.(); };
}

function boot(root) {
  const q = new URLSearchParams(location.search), rec = q.has('record');
  const win = root.querySelector('[data-tour-window]');
  const convs = [...win.querySelectorAll('.mcp-conv')];
  const reduced = matchMedia('(prefers-reduced-motion: reduce)').matches && !rec && !q.has('t');

  prepare(win);
  const steps = [pause(script.lead ?? .9)];
  convs.forEach((c, i) => {
    const k = i + 1, me = `@${c.dataset.tour}`;
    steps.push(chapter(String(k).padStart(2, '0'), c.dataset.title || `Example ${k}`), mark(`conv-${k}`));
    if (i) steps.push(hide(`@${convs[i - 1].dataset.tour}`, { dur: .45 }), set(`@tab-${k - 1}`, { class: '-is-on' }));
    steps.push(set(`@tab-${k}`, { class: '+is-on' }), show(me, { dur: .5, ease: 'out', wait: i ? .25 : 0, block: true }));
    steps.push(...conversation(win, c.querySelector('[data-ck-thread]'), { ...script, prefix: `c${k}-` }));
    steps.push(mark(`conv-${k}-end`), pause(script.between ?? 1.8));
  });
  steps.push(hide(`@${convs.at(-1).dataset.tour}`, { dur: .45 }), set(`@tab-${convs.length}`, { class: '-is-on' }), mark('end'));
  const tour = new Tour(root, { ...script, steps: [...steps, ...(script.steps || [])] });
  root.tour = tour;
  win.removeAttribute('aria-hidden');                    // real text, and a live ending
  const off = [() => tour.destroy(), copyButtons(win), tabs(win), foldable(win)];
  const M = tour.marks;

  const jump = (t, play) => { tour.pause(); tour.render(t, true); if (play && !tour.still) tour.play(); };
  const click = (e) => {
    const tab = e.target.closest('[data-mcp-conv]'), add = e.target.closest('[data-mcp-jump]');
    if (tab) { e.preventDefault(); const k = tab.dataset.mcpConv; jump(reduced ? M[`conv-${k}-end`] : M[`conv-${k}`], true); }
    if (add) { e.preventDefault(); jump(tour.duration, false); }
  };
  win.addEventListener('click', click);
  off.push(() => win.removeEventListener('click', click));

  if (reduced) tour.render(M['conv-1-end'], true);       // a complete first conversation; the tabs show the others
  else if (!rec && !tour.still) {
    const t0 = setTimeout(() => tour.play(), 500);
    const vis = () => { if (document.hidden) tour.pause(); else if (tour.t < tour.duration - .05 && tour.t > 0) tour.play(); };
    document.addEventListener('visibilitychange', vis);
    off.push(() => { clearTimeout(t0); document.removeEventListener('visibilitychange', vis); });
  }
  return () => off.forEach((f) => f());
}

/* tour.js: a declarative product-tour engine. The shared foundation for every StyleFeatures demo film.
   Full reference: README.md beside this file. In short:

     import { Tour, click, type, show, zoom, chapter } from './tour.js';
     new Tour(rootElement, { size: [1200, 750], steps: [ chapter('01 / 03', 'Start <em>here</em>', 'One line.'),
                                                        click('@new'), show('@modal'), type('@name', 'Hello') ] });

   Everything on screen is a pure function of one number, t (seconds). Each frame the engine works out the
   product's state at t (classes, attributes, text, CSS variables, scroll positions), the camera, the fake
   cursor and the overlays, and writes only what changed. So any moment can be rendered on its own:
   ?t=12.5 freezes there, seek(t) jumps there, and a scroll, a clock or a screen recorder can all drive it.

   Selectors ('@name' is short for [data-tour="name"]) are measured against the product as it is at the moment
   each step happens, and measured again whenever the layout changes (fonts, resize, your CSS), so editing the
   product never breaks the script. */

const cl = (x) => (x < 0 ? 0 : x > 1 ? 1 : x);
export const ease = (t) => t * t * t * (t * (t * 6 - 15) + 10);           // smootherstep: settles, no overshoot
const lerp = (a, b, t) => a + (b - a) * t;
const rnd = (n) => { const x = Math.sin(n * 91.7 + 13.1) * 43758.5453; return x - Math.floor(x); };
const sel = (s) => (typeof s === 'string' ? s.replace(/@([\w-]+)/g, '[data-tour="$1"]') : s);
const fmtTime = (s) => `${Math.floor(s / 60)}:${String(Math.floor(s % 60)).padStart(2, '0')}`;

/* ── step builders ─────────────────────────────────────────────────────────────────────────────
   Pointer steps run one after another on the script's clock. Side steps (zoom, show, hide, set, tween,
   chapter, caption) start at the current moment and let the next step start with them.
   Any step takes { at: seconds } to pin it, { wait: seconds } to start later, { parallel: true }
   so a pointer step doesn't hold up the next one, { block: true } so a side step does. */
export const move = (to, o = {}) => ({ ...o, do: 'move', to });
export const click = (to, o = {}) => ({ ...o, do: 'click', to });
export const dblclick = (to, o = {}) => ({ ...o, do: 'dblclick', to });
export const hover = (to, o = {}) => ({ ...o, do: 'hover', to });
export const type = (el, text, o = {}) => ({ ...o, do: 'type', el, text });
export const drag = (handle, o = {}) => ({ ...o, do: 'drag', handle });
export const scroll = (el, to, o = {}) => ({ ...o, do: 'scroll', el, to });
export const key = (keys, o = {}) => ({ ...o, do: 'key', keys: [].concat(keys) });
export const zoom = (to, z = 'fit', o = {}) => ({ ...o, do: 'zoom', to, z });
export const unzoom = (o = {}) => ({ ...o, do: 'zoom', to: null, z: 1 });
export const show = (el, o = {}) => ({ ...o, do: 'show', el });
export const hide = (el, o = {}) => ({ ...o, do: 'hide', el });
export const set = (el, changes, o = {}) => ({ ...o, do: 'set', el, changes });
export const tween = (el, prop, from, to, o = {}) => ({ ...o, do: 'tween', el, prop, from, to });
export const chapter = (n, title, line = '', o = {}) => ({ ...o, do: 'chapter', n, title, line });
export const caption = (text, o = {}) => ({ ...o, do: 'caption', text });
export const pause = (dur = 1) => ({ do: 'pause', dur });
export const stream = (el, o = {}) => ({ ...o, do: 'stream', el });   // reveal matches one after another, like output arriving
export const tap = click;                                                 // the same step; reads better in a touch film
export const longpress = (to, o = {}) => ({ ...o, do: 'longpress', to }); // press and hold; it fires after { hold } s
export const swipe = (on, o = {}) => ({ ...o, do: 'swipe', on });         // a finger flick: { by, scroll } or { prop, from, to } (README)
export const mark = (name, o = {}) => ({ ...o, do: 'mark', name });       // a named moment: tour.api.marks[name] is its time, and the list is in order (README)

/* eases for show / hide / tween: { ease: 'out' | 'ios' | 'spring' | (t) => t }. Default: smootherstep.
   'ios' is a critically damped spring (UIKit pushes and sheets), 'spring' overshoots by about 3%. */
export const eases = {
  linear: (t) => t,
  out: (t) => 1 - Math.pow(1 - t, 3),
  ios: (t) => (t >= 1 ? 1 : (1 - (1 + 9 * t) * Math.exp(-9 * t)) / (1 - 10 * Math.exp(-9))),
  spring: (t) => (t >= 1 ? 1 : 1 - Math.exp(-6 * t) * (Math.cos(5.3 * t) + 1.13 * Math.sin(5.3 * t))),
};
const easeOf = (e) => (typeof e === 'function' ? e : eases[e] || ease);

/* when each character of a typed string lands. rhythm: undefined (even, as before) | 'human' (beats between
   words, a reach for symbols, the odd hesitation) | 'stream' (chunks, like a model's reply arriving) */
function keyTimes(txt, cps, seed, rhythm, c) {
  const at = [], b = 1 / cps;
  if (rhythm === 'stream') {
    for (let i = 0, j = 0; i < txt.length; j++) { const n = 1 + Math.floor(rnd(seed * 13 + j) * 5); c += b * n * (.5 + rnd(seed * 29 + j)); for (let m = 0; m < n && i < txt.length; m++, i++) at.push(c); }
    return at;
  }
  for (let i = 0; i < txt.length; i++) {
    let d = b * (.55 + .9 * rnd(seed * 31 + i));
    if (rhythm === 'human') {
      const ch = txt[i], pv = txt[i - 1] || '';
      if (pv === ' ') d += b * (.3 + .9 * rnd(seed * 37 + i));
      if (/[-/.:=_@|&>~"'`]/.test(ch)) d += b * .7;
      if (/[,;!?]/.test(pv) || (pv === '.' && ch === ' ')) d += b * 1.4;
      if (ch === pv && /\w/.test(ch)) d *= .6;
      if (i > 2 && rnd(seed * 43 + i) < .035) d += .2 + .25 * rnd(seed * 47 + i);
    }
    c += d; at.push(c);
  }
  return at;
}

/* load harvested fragments: <div data-tour-include="fragments/home.html"></div>. Await it before new Tour(). */
export async function include(root) {
  await Promise.all([...root.querySelectorAll('[data-tour-include]')].map(async (el) => {
    const r = await fetch(el.dataset.tourInclude); el.innerHTML = r.ok ? await r.text() : ''; el.removeAttribute('data-tour-include');
    if (!r.ok) console.warn('[tour] could not load', r.url);
  }));
}

/* ?record for a page with several tours in one frame (demo/versus, demo/deck): makes el the record stage, the box
   of ?ratio= centred on near-black with the rest of the page hidden, exactly as a single film gets it. Build each
   Tour inside it with { record: 'page' } and drive them from the page. Returns { w, h, ratio } and keeps it current. */
export function recordStage(el, q = new URLSearchParams(location.search)) {
  document.documentElement.classList.add('tour-record', 'sf-clean');
  el.setAttribute('data-tour-root', ''); el.classList.add('is-record');
  const r = (q.get('ratio') || '16:9').split(':').map(Number), box = { w: 0, h: 0, ratio: r.join(':') };
  const fit = () => {
    let w = innerWidth, h = innerHeight;
    if (r.length === 2 && r[0] > 0) { const a = r[0] / r[1]; if (w / h > a) w = Math.round(h * a); else h = Math.round(w / a); }
    box.w = w; box.h = h; el.style.setProperty('--rw', w + 'px'); el.style.setProperty('--rh', h + 'px');
  };
  fit(); addEventListener('resize', fit);
  return box;
}

const BLOCKS = new Set(['move', 'click', 'dblclick', 'hover', 'type', 'drag', 'scroll', 'key', 'pause', 'stream', 'longpress', 'swipe']);
const POINT = new Set(['move', 'click', 'dblclick', 'hover', 'drag', 'longpress', 'swipe']);

/* ── window chromes ─────────────────────────────────────────────────────────────────────────── */
const CHROME = {
  browser: (w) => `<div class="tour-chrome" data-kind="browser"><span class="tour-lights"><i></i><i></i><i></i></span>
    <span class="tour-navs"><svg viewBox="0 0 16 16"><path d="M10 3 5 8l5 5"/></svg><svg viewBox="0 0 16 16"><path d="m6 3 5 5-5 5"/></svg></span>
    <span class="tour-url"><svg viewBox="0 0 16 16"><path d="M5 7V5a3 3 0 0 1 6 0v2M4 7h8v6H4z"/></svg>${w.dataset.url || 'yourproduct.com'}</span>
    <span class="tour-navs is-end"><svg viewBox="0 0 16 16"><path d="M8 3v7M5 6l3-3 3 3M3 9v4h10V9"/></svg><svg viewBox="0 0 16 16"><path d="M8 3v10M3 8h10"/></svg></span></div>`,
  app: (w) => `<div class="tour-chrome" data-kind="app"><span class="tour-lights"><i></i><i></i><i></i></span><b>${w.dataset.title || ''}</b></div>`,
  terminal: (w) => `<div class="tour-chrome" data-kind="terminal"><span class="tour-lights"><i></i><i></i><i></i></span><b>${w.dataset.title || ''}</b></div>`,
  phone: () => `<div class="tour-chrome" data-kind="phone"><b>9:41</b><span class="tour-notch"></span><span class="tour-status"><i></i><i></i><i></i></span></div>`,
  none: () => '',
};

/* ── cursor art (hotspot at 0,0) ─────────────────────────────────────────────────────────────── */
const CURSORS = `
<svg class="tour-arrow" width="22" height="30" viewBox="-1 -1 16 23"><path d="M0 0V16.6L4.3 12.6L7.2 19.4L10 18.2L7.2 11.6H13Z" stroke-linejoin="round"/></svg>
<svg class="tour-hand" width="24" height="26" viewBox="0 0 20 22"><path d="M7 1.4c.9 0 1.6.7 1.6 1.6V9h.3V7.5c0-.8.7-1.4 1.5-1.4s1.5.6 1.5 1.4v1.9h.3V8.3c0-.8.7-1.4 1.5-1.4s1.5.6 1.5 1.4v1.5h.3v-.6c0-.8.6-1.3 1.3-1.3.8 0 1.4.6 1.4 1.3V15c0 3.4-2.5 6-5.8 6h-1.6c-2 0-3.4-.8-4.6-2.3l-4.1-5.1c-.6-.7-.5-1.7.2-2.2.7-.5 1.6-.4 2.2.2l.7.9V3c0-.9.7-1.6 1.6-1.6Z" stroke-linejoin="round"/></svg>
<svg class="tour-beam" width="10" height="24" viewBox="0 0 10 24"><path d="M2 1.5h2.2c.5 0 .8.3.8.8v19.4c0 .5-.3.8-.8.8H2M8 1.5H5.8c-.5 0-.8.3-.8.8v19.4c0 .5.3.8.8.8H8M3 12h4" fill="none" stroke-linecap="round"/></svg>`;

export class Tour {
